// Data Processing and Metrics Calculation
const items = $input.all();
const processedData = [];

// Process each platform's data
for (const item of items) {
  const platformData = item.json;
  const platform = determinePlatform(platformData);

  if (platform) {
    const metrics = calculateMetrics(platformData, platform);
    const normalizedData = {
      platform: platform,
      brand_name: $('Workflow Variables').first().json.brand_name,
      collection_date: new Date().toISOString(),
      metrics: metrics,
      raw_data: platformData,
      processing_timestamp: Date.now()
    };

    processedData.push(normalizedData);
  }
}

// Helper function to determine platform from data structure
function determinePlatform(data) {
  if (data.media_type !== undefined) return 'instagram';
  if (data.message !== undefined && data.created_time !== undefined) return 'facebook';
  if (data.public_metrics !== undefined && data.lang !== undefined) return 'twitter';
  if (data.shares !== undefined) return 'linkedin';
  if (data.video !== undefined) return 'tiktok';
  if (data.snippet !== undefined && data.snippet.channelId !== undefined) return 'youtube';
  return null;
}

// Helper function to calculate standardized metrics
function calculateMetrics(data, platform) {
  const metrics = {
    engagement_rate: 0,
    reach: 0,
    impressions: 0,
    likes: 0,
    comments: 0,
    shares: 0,
    followers_growth: 0,
    performance_score: 0
  };

  switch (platform) {
    case 'instagram':
      metrics.likes = data.like_count || 0;
      metrics.comments = data.comments_count || 0;
      metrics.engagement_rate = calculateEngagementRate(metrics.likes, metrics.comments, data.followers_count || 1000);
      break;

    case 'facebook':
      metrics.likes = data.likes?.summary?.total_count || 0;
      metrics.comments = data.comments?.summary?.total_count || 0;
      metrics.shares = data.shares?.count || 0;
      metrics.engagement_rate = calculateEngagementRate(metrics.likes + metrics.comments + metrics.shares, 0, data.fan_count || 1000);
      break;

    case 'twitter':
      if (data.public_metrics) {
        metrics.likes = data.public_metrics.like_count || 0;
        metrics.comments = data.public_metrics.reply_count || 0;
        metrics.shares = data.public_metrics.retweet_count || 0;
        metrics.impressions = data.public_metrics.impression_count || 0;
        metrics.engagement_rate = calculateEngagementRate(metrics.likes + metrics.comments + metrics.shares, 0, metrics.impressions || 1);
      }
      break;

    case 'linkedin':
      // LinkedIn metrics processing
      metrics.likes = data.likes || 0;
      metrics.comments = data.comments || 0;
      metrics.shares = data.shares || 0;
      break;

    case 'tiktok':
      // TikTok metrics processing
      if (data.stats) {
        metrics.likes = data.stats.diggCount || 0;
        metrics.comments = data.stats.commentCount || 0;
        metrics.shares = data.stats.shareCount || 0;
        metrics.reach = data.stats.playCount || 0;
      }
      break;

    case 'youtube':
      // YouTube metrics processing
      if (data.statistics) {
        metrics.likes = parseInt(data.statistics.likeCount) || 0;
        metrics.comments = parseInt(data.statistics.commentCount) || 0;
        metrics.reach = parseInt(data.statistics.viewCount) || 0;
      }
      break;
  }

  // Calculate performance score (0-100)
  metrics.performance_score = calculatePerformanceScore(metrics, platform);

  return metrics;
}

// Helper function to calculate engagement rate
function calculateEngagementRate(totalEngagements, additionalEngagements, followerCount) {
  const total = totalEngagements + additionalEngagements;
  return followerCount > 0 ? (total / followerCount) * 100 : 0;
}

// Helper function to calculate performance score
function calculatePerformanceScore(metrics, platform) {
  let score = 0;

  // Engagement rate weight: 40%
  score += Math.min(metrics.engagement_rate * 4, 40);

  // Reach/Impressions weight: 30%
  const reachScore = Math.log10(Math.max(metrics.reach || metrics.impressions || 1, 1)) * 3;
  score += Math.min(reachScore, 30);

  // Total interactions weight: 30%
  const totalInteractions = metrics.likes + metrics.comments + metrics.shares;
  const interactionScore = Math.log10(Math.max(totalInteractions, 1)) * 3;
  score += Math.min(interactionScore, 30);

  return Math.min(Math.round(score), 100);
}

return processedData.map(data => ({ json: data }));

// Competitive Analysis Module
const items = $input.all();
const brandData = items[0].json;
const competitiveBrands = $('Workflow Variables').first().json.competitive_brands;

if (!competitiveBrands || competitiveBrands === '') {
  return [{ json: { ...brandData, competitive_analysis: 'No competitive brands configured' } }];
}

const competitors = competitiveBrands.split(',').map(brand => brand.trim());
const competitiveInsights = {
  brand_performance: brandData.metrics,
  competitive_landscape: [],
  market_position: '',
  opportunities: [],
  threats: []
};

// Analyze competitive positioning
const avgEngagementRate = brandData.metrics.engagement_rate;
const avgPerformanceScore = brandData.metrics.performance_score;

// Market position analysis
if (avgPerformanceScore >= 80) {
  competitiveInsights.market_position = 'Market Leader';
} else if (avgPerformanceScore >= 60) {
  competitiveInsights.market_position = 'Strong Competitor';
} else if (avgPerformanceScore >= 40) {
  competitiveInsights.market_position = 'Market Follower';
} else {
  competitiveInsights.market_position = 'Needs Improvement';
}

// Identify opportunities based on performance
if (avgEngagementRate < 2.0) {
  competitiveInsights.opportunities.push('Improve content engagement strategies');
}
if (brandData.metrics.reach < 10000) {
  competitiveInsights.opportunities.push('Expand audience reach through targeted campaigns');
}
if (brandData.metrics.followers_growth < 5) {
  competitiveInsights.opportunities.push('Implement follower growth initiatives');
}

// Identify potential threats
if (avgEngagementRate < 1.0) {
  competitiveInsights.threats.push('Below-average engagement may indicate content quality issues');
}
if (brandData.metrics.performance_score < 30) {
  competitiveInsights.threats.push('Overall performance significantly below industry standards');
}

const result = {
  ...brandData,
  competitive_analysis: competitiveInsights,
  analysis_timestamp: new Date().toISOString()
};

return [{ json: result }];

// Report Generation Module
const items = $input.all();
const analysisData = items[0].json;
const variables = $('Workflow Variables').first().json;

// Generate comprehensive report
const report = {
  report_id: `report_${Date.now()}`,
  brand_name: variables.brand_name,
  report_date: new Date().toISOString(),
  report_period: `Last ${variables.days_to_analyze} days`,
  platforms_analyzed: variables.platforms_enabled.split(','),

  // Executive Summary
  executive_summary: {
    overall_performance_score: analysisData.metrics?.performance_score || 0,
    total_engagement: (analysisData.metrics?.likes || 0) + (analysisData.metrics?.comments || 0) + (analysisData.metrics?.shares || 0),
    engagement_rate: analysisData.metrics?.engagement_rate || 0,
    reach: analysisData.metrics?.reach || 0,
    sentiment_score: extractSentimentScore(analysisData.ai_analysis),
    market_position: analysisData.competitive_analysis?.market_position || 'Not analyzed'
  },

  // Platform Performance
  platform_performance: generatePlatformBreakdown(analysisData),

  // AI Insights
  ai_insights: analysisData.ai_analysis || 'AI analysis not performed',

  // Competitive Analysis
  competitive_insights: analysisData.competitive_analysis || 'Competitive analysis not performed',

  // Key Metrics
  key_metrics: {
    followers_growth: analysisData.metrics?.followers_growth || 0,
    engagement_rate: analysisData.metrics?.engagement_rate || 0,
    reach: analysisData.metrics?.reach || 0,
    impressions: analysisData.metrics?.impressions || 0,
    performance_score: analysisData.metrics?.performance_score || 0
  },

  // Recommendations
  recommendations: generateRecommendations(analysisData),

  // Action Items
  action_items: generateActionItems(analysisData),

  // Report Metadata
  metadata: {
    generated_by: 'Brand Digital Presence Monitor',
    workflow_version: '1.0',
    data_sources: variables.platforms_enabled.split(','),
    analysis_depth: variables.include_sentiment_analysis ? 'Comprehensive' : 'Basic',
    competitive_analysis: variables.include_competitive_analysis
  }
};

// Helper function to extract sentiment score from AI analysis
function extractSentimentScore(aiAnalysis) {
  if (!aiAnalysis || typeof aiAnalysis !== 'string') return 0;

  try {
    const analysis = JSON.parse(aiAnalysis);
    if (analysis.sentiment && analysis.sentiment.overall_score) {
      return analysis.sentiment.overall_score;
    }
  } catch (e) {
    // If parsing fails, try to extract score with regex
    const scoreMatch = aiAnalysis.match(/sentiment.*?score.*?(\d+(?:\.\d+)?)/i);
    if (scoreMatch) {
      return parseFloat(scoreMatch[1]);
    }
  }

  return 0;
}

// Helper function to generate platform breakdown
function generatePlatformBreakdown(data) {
  const platforms = {};

  if (data.platform) {
    platforms[data.platform] = {
      engagement_rate: data.metrics?.engagement_rate || 0,
      performance_score: data.metrics?.performance_score || 0,
      total_interactions: (data.metrics?.likes || 0) + (data.metrics?.comments || 0) + (data.metrics?.shares || 0),
      reach: data.metrics?.reach || data.metrics?.impressions || 0
    };
  }

  return platforms;
}

// Helper function to generate recommendations
function generateRecommendations(data) {
  const recommendations = [];
  const metrics = data.metrics || {};

  if (metrics.engagement_rate < 2.0) {
    recommendations.push({
      priority: 'High',
      category: 'Engagement',
      recommendation: 'Focus on creating more engaging content to improve engagement rates',
      expected_impact: 'Increase engagement rate by 0.5-1.5%'
    });
  }

  if (metrics.performance_score < 50) {
    recommendations.push({
      priority: 'High',
      category: 'Overall Performance',
      recommendation: 'Comprehensive content strategy review and optimization needed',
      expected_impact: 'Improve overall performance score by 20-30 points'
    });
  }

  if (metrics.reach < 10000) {
    recommendations.push({
      priority: 'Medium',
      category: 'Reach',
      recommendation: 'Implement paid promotion strategies to expand audience reach',
      expected_impact: 'Increase reach by 25-50%'
    });
  }

  return recommendations;
}

// Helper function to generate action items
function generateActionItems(data) {
  const actionItems = [];
  const metrics = data.metrics || {};

  actionItems.push({
    task: 'Review and optimize posting schedule',
    deadline: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
    assignee: 'Social Media Manager',
    priority: 'Medium'
  });

  if (metrics.engagement_rate < 1.5) {
    actionItems.push({
      task: 'Conduct content audit and develop engagement improvement plan',
      deadline: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
      assignee: 'Content Team',
      priority: 'High'
    });
  }

  if (data.competitive_analysis?.opportunities?.length > 0) {
    actionItems.push({
      task: 'Implement competitive opportunity strategies',
      deadline: new Date(Date.now() + 21 * 24 * 60 * 60 * 1000).toISOString(),
      assignee: 'Marketing Team',
      priority: 'Medium'
    });
  }

  return actionItems;
}

return [{ json: report }];

