// Error Handling and Logging Module
const items = $input.all();
const errors = [];
const warnings = [];
const processingLog = [];

// Collect and analyze any errors or issues
for (const item of items) {
  const data = item.json;

  // Check for data quality issues
  if (!data.brand_name || data.brand_name === '') {
    errors.push('Brand name is missing or empty');
  }

  if (!data.platforms_analyzed || data.platforms_analyzed.length === 0) {
    warnings.push('No platforms were successfully analyzed');
  }

  if (data.executive_summary?.overall_performance_score === 0) {
    warnings.push('Performance score is zero - check data collection');
  }

  if (!data.notion_database_id) {
    errors.push('Notion database ID is missing - reports will not be stored');
  }

  // Log successful operations
  processingLog.push({
    timestamp: new Date().toISOString(),
    operation: 'Brand monitoring completed',
    brand: data.brand_name,
    platforms: data.platforms_analyzed?.length || 0,
    performance_score: data.executive_summary?.overall_performance_score || 0,
    status: errors.length === 0 ? 'success' : 'warning'
  });
}

const errorReport = {
  workflow_execution: {
    execution_id: `exec_${Date.now()}`,
    execution_date: new Date().toISOString(),
    status: errors.length === 0 ? (warnings.length === 0 ? 'success' : 'success_with_warnings') : 'error',
    errors: errors,
    warnings: warnings,
    processing_log: processingLog
  },
  next_execution: {
    scheduled_time: getNextExecutionTime(),
    estimated_duration: '5-10 minutes',
    platforms_to_monitor: $('Workflow Variables').first().json.platforms_enabled?.split(',') || []
  },
  system_health: {
    data_quality_score: calculateDataQualityScore(errors, warnings),
    api_status: 'operational', // This would be dynamically determined in a real implementation
    storage_status: errors.some(e => e.includes('Notion')) ? 'degraded' : 'operational'
  }
};

// Helper function to calculate next execution time
function getNextExecutionTime() {
  const now = new Date();
  const tomorrow = new Date(now);
  tomorrow.setDate(tomorrow.getDate() + 1);
  tomorrow.setHours(8, 0, 0, 0); // 8:00 AM tomorrow
  return tomorrow.toISOString();
}

// Helper function to calculate data quality score
function calculateDataQualityScore(errors, warnings) {
  let score = 100;
  score -= errors.length * 20; // Each error reduces score by 20
  score -= warnings.length * 5; // Each warning reduces score by 5
  return Math.max(score, 0);
}

return [{ json: errorReport }];
